import{_ as i,o as n,c as t,a2 as a}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Division unifiée des niveaux de culture","description":"","frontmatter":{},"headers":[],"relativePath":"fr/14-修炼境界统一划分.md","filePath":"fr/14-修炼境界统一划分.md","lastUpdated":1789183869000}'),s={name:"fr/14-修炼境界统一划分.md"};function r(d,e,o,u,l,c){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="division-unifiee-des-niveaux-de-culture" tabindex="-1">Division unifiée des niveaux de culture <a class="header-anchor" href="#division-unifiee-des-niveaux-de-culture" aria-label="Permalink to &quot;Division unifiée des niveaux de culture&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>14</td></tr><tr><td>Module</td><td>Lois cosmiques et systèmes de culture</td></tr><tr><td>Mots-clés</td><td>Division des niveaux, Norme unifiée, Neuf niveaux, Référencement inter-systèmes, Certification par les ancres</td></tr></tbody></table><h2 id="i-necessite-de-la-division-unifiee-des-niveaux" tabindex="-1">I. Nécessité de la division unifiée des niveaux <a class="header-anchor" href="#i-necessite-de-la-division-unifiee-des-niveaux" aria-label="Permalink to &quot;I. Nécessité de la division unifiée des niveaux&quot;">​</a></h2><p>Avant l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, il existait des milliers de systèmes de culture dans Heng Yuan Zhou, chacun avec ses propres normes indépendantes de division des niveaux. Ce système chaotique de niveaux a conduit à une série de problèmes : la force des cultivateurs de différents systèmes était difficile à comparer, la communication et la collaboration inter-systèmes manquaient de langage commun, l&#39;allocation des ressources et l&#39;évaluation du statut social manquaient de base unifiée, et même l&#39;injustice grave de « même niveau, force différente » est apparue.</p><p>Après l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, pour résoudre ce problème, sous la direction du « Comité des normes de culture » relevant du Parlement de la République des Dix Mille Races, avec les cultivateurs représentatifs des Trois Cents Systèmes, cette « Norme unifiée de division des niveaux de culture » a été formulée après une recherche et une démonstration de longue durée. Cette norme ne repose pas sur les noms de niveaux d&#39;un système unique, mais utilise quatre dimensions comme indicateurs centraux — la profondeur de compréhension des lois de l&#39;Origine de l&#39;univers par le cultivateur, la précision de la manipulation énergétique, le degré d&#39;évolution de la conscience et la contribution au réseau symbiotique — établissant un système de division des niveaux universel inter-systèmes.</p><p>Le principe central de la division unifiée des niveaux est « valoriser la substance plutôt que le nom » : quel que soit le système utilisé par le cultivateur ou le nom de niveau qu&#39;il emploie, tant que sa substance atteint le niveau correspondant de la norme unifiée, il est reconnu à ce niveau. Ce principe garantit l&#39;équité et l&#39;objectivité de l&#39;évaluation des niveaux.</p><h2 id="ii-apercu-des-neuf-niveaux" tabindex="-1">II. Aperçu des neuf niveaux <a class="header-anchor" href="#ii-apercu-des-neuf-niveaux" aria-label="Permalink to &quot;II. Aperçu des neuf niveaux&quot;">​</a></h2><p>La norme unifiée de division des niveaux divise le parcours évolutif du cultivateur en neuf grands niveaux, du bas vers le haut :</p><table tabindex="0"><thead><tr><th>N° de niveau</th><th>Nom du niveau</th><th>Caractéristiques fondamentales</th><th>Niveau approximativement correspondant des Trois Fondements de l&#39;Origine</th><th>Positionnement du rôle social</th></tr></thead><tbody><tr><td>Premier</td><td>Niveau de Perception de l&#39;Origine</td><td>Percevoir préliminairement l&#39;existence de l&#39;énergie et des lois cosmiques, commencer la culture formelle</td><td>Aperçu initial / Perception de la Vie / Reconnaissance de l&#39;Espace</td><td>Débutant</td></tr><tr><td>Deuxième</td><td>Niveau de Condensation de l&#39;Origine</td><td>Absorber et condenser l&#39;énergie de manière stable, établir une circulation interne de base</td><td>Déduction / Circulation / Maîtrise de l&#39;Espace</td><td>Cultivateur junior</td></tr><tr><td>Troisième</td><td>Niveau de Transformation de l&#39;Origine</td><td>Purification énergétique atteignant un niveau élevé, transformer l&#39;énergie en diverses applications</td><td>Itération / Génération / Transformation de l&#39;Espace</td><td>Cultivateur intermédiaire</td></tr><tr><td>Quatrième</td><td>Niveau de Loi de l&#39;Origine</td><td>Commencer à comprendre et manipuler les lois, fusion initiale de l&#39;énergie et des lois</td><td>Intégration / Transformation de la Vie / Loi de l&#39;Espace</td><td>Cultivateur avancé</td></tr><tr><td>Cinquième</td><td>Niveau de Dao de l&#39;Origine</td><td>Compréhension profonde des lois d&#39;un domaine, formant son « Dao » personnel</td><td>Origine / Naissance de l&#39;Origine / Origine de l&#39;Espace</td><td>Cultivateur de niveau maître</td></tr><tr><td>Sixième</td><td>Niveau d&#39;Intégration du Dao</td><td>Le Dao personnel fusionne profondément avec les lois de l&#39;Origine de l&#39;univers, chaque geste conforme au Dao</td><td>Au-delà du cinquième niveau d&#39;un système unique</td><td>Cultivateur de niveau grand maître</td></tr><tr><td>Septième</td><td>Niveau de Brisement des Frontières</td><td>Briser les restrictions des lois des plans, effectuer des opérations stables entre plans</td><td>—</td><td>Expert de niveau plan</td></tr><tr><td>Huitième</td><td>Niveau de Création du Monde</td><td>Créer des mondes complets et des systèmes de lois dans l&#39;Espace d&#39;Isolement</td><td>—</td><td>Expert de niveau monde</td></tr><tr><td>Neuvième</td><td>Niveau de l&#39;Origine</td><td>Toucher l&#39;Origine de l&#39;univers, participer au réglage fin et à l&#39;optimisation des lois cosmiques</td><td>—</td><td>Expert de niveau cosmos</td></tr></tbody></table><p>Parmi les neuf niveaux, les premier à cinquième sont les « cinq niveaux de culture mortelle », atteignables par la plupart des cultivateurs grâce à leurs efforts ; les sixième à neuvième sont les « quatre niveaux de culture sacrée », nécessitant un talent, une fortune et des efforts extrêmement élevés — la percée de chaque niveau est un événement majeur de niveau cosmique.</p><h2 id="iii-normes-detaillees-de-chaque-niveau" tabindex="-1">III. Normes détaillées de chaque niveau <a class="header-anchor" href="#iii-normes-detaillees-de-chaque-niveau" aria-label="Permalink to &quot;III. Normes détaillées de chaque niveau&quot;">​</a></h2><h3 id="_3-1-premier-niveau-perception-de-l-origine" tabindex="-1">3.1 Premier niveau : Perception de l&#39;Origine <a class="header-anchor" href="#_3-1-premier-niveau-perception-de-l-origine" aria-label="Permalink to &quot;3.1 Premier niveau : Perception de l&#39;Origine&quot;">​</a></h3><p>Le niveau de Perception de l&#39;Origine est le point de départ de la culture, avec la « perception » au cœur. Les normes pour atteindre ce niveau comprennent :</p><ul><li>Percevoir de manière stable l&#39;énergie libre dans l&#39;univers (qi spirituel, force des lois, etc.)</li><li>Absorber des quantités infimes d&#39;énergie dans le corps par des méthodes de culture de base</li><li>Établir une conscience préliminaire de perception énergétique, capable de distinguer différents types d&#39;énergie</li><li>La qualité physique montre une amélioration initiale due à l&#39;infiltration énergétique</li></ul><p>Les cultivateurs du niveau de Perception de l&#39;Origine sont des « débutants » dans la société, dont la tâche principale est de poser des fondations solides et de trouver un système de culture adapté. La percée de ce niveau exige généralement plusieurs semaines à plusieurs mois de culture formelle.</p><h3 id="_3-2-deuxieme-niveau-condensation-de-l-origine" tabindex="-1">3.2 Deuxième niveau : Condensation de l&#39;Origine <a class="header-anchor" href="#_3-2-deuxieme-niveau-condensation-de-l-origine" aria-label="Permalink to &quot;3.2 Deuxième niveau : Condensation de l&#39;Origine&quot;">​</a></h3><p>Le cœur du niveau de Condensation de l&#39;Origine est la « condensation ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Absorber l&#39;énergie cosmique de manière stable et la condenser en réserves d&#39;énergie utilisables dans le corps</li><li>Établir un système de circulation interne de base, l&#39;énergie pouvant circuler dans le corps le long de chemins spécifiques</li><li>Utiliser l&#39;énergie condensée pour des applications offensives, défensives ou auxiliaires de base</li><li>La pureté énergétique atteint la norme de base, sans impuretés excessives</li></ul><p>Les cultivateurs du niveau de Condensation de l&#39;Origine possèdent déjà une identité de cultivateur de base et peuvent participer à certaines tâches de culture de bas niveau et services sociaux. La percée exige généralement plusieurs mois à plusieurs années de culture.</p><h3 id="_3-3-troisieme-niveau-transformation-de-l-origine" tabindex="-1">3.3 Troisième niveau : Transformation de l&#39;Origine <a class="header-anchor" href="#_3-3-troisieme-niveau-transformation-de-l-origine" aria-label="Permalink to &quot;3.3 Troisième niveau : Transformation de l&#39;Origine&quot;">​</a></h3><p>Le cœur du niveau de Transformation de l&#39;Origine est la « transformation ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>La purification énergétique atteint un niveau élevé, capable de transformer un type d&#39;énergie en un autre</li><li>Effectuer une interaction préliminaire entre l&#39;énergie et la matière (comme l&#39;attachement d&#39;énergie aux objets, le façonnage énergétique, etc.)</li><li>Circulation interne stable et efficace, vitesse de récupération énergétique considérablement améliorée</li><li>Commencer à percevoir l&#39;existence et le fonctionnement des lois</li></ul><p>Les cultivateurs du niveau de Transformation de l&#39;Origine sont l&#39;épine dorsale de la société, pouvant servir de mentors intermédiaires, de personnel technique, de gestionnaires de base, etc. La percée exige généralement plusieurs années à plus d&#39;une décennie de culture.</p><h3 id="_3-4-quatrieme-niveau-loi-de-l-origine" tabindex="-1">3.4 Quatrième niveau : Loi de l&#39;Origine <a class="header-anchor" href="#_3-4-quatrieme-niveau-loi-de-l-origine" aria-label="Permalink to &quot;3.4 Quatrième niveau : Loi de l&#39;Origine&quot;">​</a></h3><p>Le cœur du niveau de Loi de l&#39;Origine est la « loi ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Comprendre et manipuler préliminairement les lois fondamentales d&#39;un certain domaine</li><li>Fusion initiale de l&#39;énergie et des lois, produisant la « force de loi » — une forme d&#39;énergie d&#39;ordre supérieur</li><li>Effectuer des sorts et compétences basés sur les lois</li><li>L&#39;intensité de conscience considérablement améliorée, capable de déduction profonde et de méditation sur de longues périodes</li></ul><p>Les cultivateurs du niveau de Loi de l&#39;Origine sont des talents avancés dans la société, pouvant servir de mentors supérieurs, d&#39;experts techniques, de gestionnaires intermédiaires, etc. La percée exige généralement plus d&#39;une décennie à plusieurs décennies de culture, et constitue le premier goulot d&#39;étranglement majeur dans la vie de nombreux cultivateurs.</p><h3 id="_3-5-cinquieme-niveau-dao-de-l-origine" tabindex="-1">3.5 Cinquième niveau : Dao de l&#39;Origine <a class="header-anchor" href="#_3-5-cinquieme-niveau-dao-de-l-origine" aria-label="Permalink to &quot;3.5 Cinquième niveau : Dao de l&#39;Origine&quot;">​</a></h3><p>Le cœur du niveau de Dao de l&#39;Origine est « former le Dao ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Compréhension systématique et profonde des lois d&#39;un certain domaine, formant un « Dao » personnel unique</li><li>Le Dao personnel entre en résonance avec les lois cosmiques, capable de mobiliser la force des lois sur un plus grand rayon</li><li>Fusion profonde de l&#39;énergie et des lois, chaque geste contient la force des lois</li><li>La conscience évolue vers un niveau supérieur, capable de perception de conscience entre plans</li></ul><p>Les cultivateurs du niveau de Dao de l&#39;Origine sont les « maîtres » de la civilisation, faisant autorité dans leurs domaines respectifs, pouvant servir de conseillers de niveau civilisation, de grands mentors, de gestionnaires supérieurs, etc. La percée exige un talent et une compréhension extrêmement élevés ; de nombreux cultivateurs ne peuvent l&#39;atteindre de leur vie.</p><h3 id="_3-6-sixieme-niveau-integration-du-dao" tabindex="-1">3.6 Sixième niveau : Intégration du Dao <a class="header-anchor" href="#_3-6-sixieme-niveau-integration-du-dao" aria-label="Permalink to &quot;3.6 Sixième niveau : Intégration du Dao&quot;">​</a></h3><p>Le cœur du niveau d&#39;Intégration du Dao est « l&#39;intégration du Dao ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Le Dao personnel fusionne profondément avec les lois de l&#39;Origine de l&#39;univers, atteignant l&#39;état d&#39;« unité du ciel et de l&#39;homme »</li><li>Réécrire le fonctionnement des lois locales sur un grand rayon</li><li>La forme de vie commence à évoluer vers des dimensions supérieures, partiellement libérée des limitations du corps matériel</li><li>Créer un domaine personnel stable (domaine de lois)</li></ul><p>Les cultivateurs du niveau d&#39;Intégration du Dao sont les « grands maîtres » de la civilisation, figures de proue dans divers domaines, avec une influence significative sur la direction du développement de la civilisation. La percée est un événement de niveau cosmique, exigeant la coordination du moment, du lieu et de l&#39;harmonie humaine.</p><h3 id="_3-7-septieme-niveau-brisement-des-frontieres" tabindex="-1">3.7 Septième niveau : Brisement des Frontières <a class="header-anchor" href="#_3-7-septieme-niveau-brisement-des-frontieres" aria-label="Permalink to &quot;3.7 Septième niveau : Brisement des Frontières&quot;">​</a></h3><p>Le cœur du niveau de Brisement des Frontières est « briser les frontières ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Briser les restrictions des lois des plans, effectuer la traversée entre plans sans soutien des ancres</li><li>Opérer sur la membrane des plans, comme ouvrir des canaux entre plans, réparer les fissures des plans</li><li>Le domaine personnel peut s&#39;étendre en un petit espace indépendant</li><li>La forme de vie se haut-dimensionalise davantage, capable de survivre dans les environnements de lois de différents plans</li></ul><p>Les experts du niveau de Brisement des Frontières sont des existences de « niveau plan », capables d&#39;entreprendre de manière indépendante des tâches et responsabilités de niveau plan. La percée est extrêmement difficile ; le nombre de cultivateurs atteignant ce niveau dans tout Heng Yuan Zhou est limité.</p><h3 id="_3-8-huitieme-niveau-creation-du-monde" tabindex="-1">3.8 Huitième niveau : Création du Monde <a class="header-anchor" href="#_3-8-huitieme-niveau-creation-du-monde" aria-label="Permalink to &quot;3.8 Huitième niveau : Création du Monde&quot;">​</a></h3><p>Le cœur du niveau de Création du Monde est « la création du monde ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Créer des mondes complets dans l&#39;Espace d&#39;Isolement, y compris la matière, l&#39;énergie, les lois et la vie</li><li>Concevoir et formuler les systèmes de lois fondamentales des nouveaux mondes</li><li>Le domaine personnel peut s&#39;étendre en un monde complet</li><li>La forme de vie approche l&#39;existence de haute dimension, capable de se manifester simultanément dans plusieurs plans</li></ul><p>Les experts du niveau de Création du Monde sont des existences de « niveau monde », dont les mondes créés peuvent servir de ressources de culture, de sites d&#39;expériences, de refuges de civilisation, etc. La percée est l&#39;un des événements les plus rares de l&#39;univers.</p><h3 id="_3-9-neuvieme-niveau-l-origine" tabindex="-1">3.9 Neuvième niveau : l&#39;Origine <a class="header-anchor" href="#_3-9-neuvieme-niveau-l-origine" aria-label="Permalink to &quot;3.9 Neuvième niveau : l&#39;Origine&quot;">​</a></h3><p>Le cœur du niveau de l&#39;Origine est « l&#39;Origine ». Les normes pour l&#39;atteindre comprennent :</p><ul><li>Toucher les lois de l&#39;Origine de l&#39;univers, capable de comprendre les lois ultimes de fonctionnement de l&#39;univers</li><li>Participer au réglage fin et à l&#39;optimisation des lois cosmiques, influencer la direction évolutive de l&#39;univers</li><li>La forme de vie se connecte profondément à l&#39;Origine de l&#39;univers, presque immortelle</li><li>Mobiliser la force de l&#39;Origine à l&#39;échelle cosmique</li></ul><p>Les experts du niveau de l&#39;Origine sont des existences de « niveau cosmos », la force la plus suprême de Heng Yuan Zhou. Les cultivateurs atteignant ce niveau sont généralement appelés « experts suprêmes des plans », le groupe cible central de la « stratégie d&#39;activation à 20% » de la civilisation symbiotique.</p><h2 id="iv-mecanisme-de-certification-des-niveaux" tabindex="-1">IV. Mécanisme de certification des niveaux <a class="header-anchor" href="#iv-mecanisme-de-certification-des-niveaux" aria-label="Permalink to &quot;IV. Mécanisme de certification des niveaux&quot;">​</a></h2><p>Pour garantir l&#39;équité et l&#39;exactitude de l&#39;évaluation des niveaux, la civilisation symbiotique a établi un mécanisme strict de certification des niveaux :</p><ol><li><strong>Surveillance automatique des ancres</strong> : après connexion du cultivateur au réseau d&#39;ancres, l&#39;ancre surveille en continu des indicateurs tels que le niveau énergétique, la compréhension des lois et l&#39;intensité de conscience ; lorsque les indicateurs atteignent la norme d&#39;un nouveau niveau, elle le signale automatiquement</li><li><strong>Évaluation du Comité des normes</strong> : pour les percées de niveau quatrième et au-dessus, une évaluation formelle doit être organisée par le Comité des normes de culture, couvrant trois aspects : test théorique, test de combat pratique et évaluation des contributions</li><li><strong>Annonce publique et période d&#39;opposition</strong> : après la réussite de l&#39;évaluation, une annonce publique de trente jours suit ; pendant cette période, toute vie peut soulever des objections, et si une objection est retenue, une ré-évaluation est requise</li><li><strong>Délivrance du certificat de niveau</strong> : après la fin de la période d&#39;annonce sans objections, le réseau d&#39;ancres délivre un certificat de niveau unifié, et les informations du certificat sont inscrites dans la base de données de la civilisation</li></ol><h2 id="v-niveaux-et-droits-et-obligations-sociaux-correspondants" tabindex="-1">V. Niveaux et droits et obligations sociaux correspondants <a class="header-anchor" href="#v-niveaux-et-droits-et-obligations-sociaux-correspondants" aria-label="Permalink to &quot;V. Niveaux et droits et obligations sociaux correspondants&quot;">​</a></h2><p>Les cultivateurs de différents niveaux jouissent de droits différents et assument des obligations différentes dans la civilisation symbiotique :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Droits fondamentaux</th><th>Obligations fondamentales</th></tr></thead><tbody><tr><td>Perception – Condensation de l&#39;Origine</td><td>Accès gratuit aux ressources de culture de base, droit d&#39;utilisation des lieux publics de culture</td><td>Respecter l&#39;éthique de la culture, participer aux services communautaires de base</td></tr><tr><td>Transformation – Loi de l&#39;Origine</td><td>Droit d&#39;allocation de ressources avancées, droit de candidature au statut de mentor, droit de mobilité interrégionale</td><td>Guider les cultivateurs débutants, participer à la R&amp;D technologique ou aux services sociaux</td></tr><tr><td>Dao – Intégration du Dao</td><td>Droit d&#39;allocation de ressources de haut niveau, droit d&#39;accès aux niveaux supérieurs des ancres, droit de participation aux décisions de la civilisation</td><td>Entreprendre des projets de recherche de niveau civilisation, maintenir la stabilité des ancres régionales</td></tr><tr><td>Brisement des Frontières – Création du Monde</td><td>Droit d&#39;allocation de ressources de niveau plan, droit de création d&#39;espaces indépendants, droit de participation aux affaires des plans</td><td>Entreprendre des tâches de niveau plan, maintenir la stabilité des membranes des plans, participer aux affaires inter-plans</td></tr><tr><td>l&#39;Origine</td><td>Droit d&#39;allocation de ressources de niveau cosmos, droit de participation au réglage fin des lois, droit de participation aux décisions suprêmes de la civilisation</td><td>Maintenir la stabilité globale de l&#39;univers, guider la direction de l&#39;évolution de la civilisation, former des talents de réserve</td></tr></tbody></table><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La norme unifiée de division des niveaux de culture est l&#39;une des infrastructures du système de culture de la Civilisation Symbiotique de l&#39;Ancre. Elle fournit une « mesure » commune aux Trois Cents Systèmes de Culture, rendant possible la communication, la collaboration et la compétition inter-systèmes, et fournissant une base objective pour l&#39;allocation des ressources, la gouvernance sociale et la formation des talents. La division des neuf niveaux ne vise pas à créer des différences hiérarchiques, mais à marquer clairement le stade évolutif de chaque cultivateur, lui fournissant le soutien et l&#39;orientation les plus adaptés. L&#39;élévation des niveaux n&#39;est pas une fin, mais un nouveau point de départ vers une évolution symbiotique de niveau supérieur.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>10-三百套本源修炼体系总览 (Aperçu des Trois Cents Systèmes de Culture de l&#39;Origine)</li><li>17-位面至高强者标准 (Normes des experts suprêmes des plans)</li><li>29-共生度评估体系 (Système d&#39;évaluation du degré de symbiose)</li></ul>',57)])])}const v=i(s,[["render",r]]);export{p as __pageData,v as default};
